<?php
require_once __DIR__.'/job_report_export.php';
function auditReportName(array $data,string $extension): string {return 'AuditLog_'.$data['period']['filename'].'.'.$extension;}
function auditReportHtml(array $data): string {
    $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
    $wrap=static function(string $text,int $length)use($e):string{return implode('<br>',array_map($e,jrWrapLines($text,static fn($s)=>mb_strlen($s)<=$length)));};
    $html='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>System Audit Log Report</title><style>'.brandDocumentStyles().'@page{margin:28px 28px 38px}body{font:9px "DejaVu Sans",sans-serif;color:#182236;background:#fff}h1{font-size:19px;margin:14px 0 8px}p{line-height:1.6;overflow-wrap:break-word}.rule{border-top:2px solid #d97706;margin-top:10px}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}tr{page-break-inside:avoid}td,th{text-align:left;vertical-align:top;padding:6px;border-bottom:1px solid #dde3eb;word-wrap:break-word;line-height:1.45}th{background:#f3f5f8;color:#58657a}small{font-size:8px;color:#58657a}.privacy{color:#58657a;font-size:8px}@media print{button{display:none}}</style></head><body>'.brandDocumentHtml(30).'<div class="rule"></div><h1>SYSTEM AUDIT LOG REPORT</h1><p><strong>Reporting Period:</strong> '.$e($data['period']['label']).'<br><strong>Applied Filters:</strong> '.$wrap($data['filters'],120).'<br><strong>Generated:</strong> '.$e($data['generated_at']).' (Asia/Manila)<br><strong>Generated By:</strong> '.$e($data['actor']['name']).' / USER-'.$data['actor']['id'].'<br><strong>Total Matching Audit Records:</strong> '.$data['total'].'</p><p class="privacy">Confidential - authorized management use only. Historical outcomes are not inferred. Original free-text metadata and confidential case references are withheld.</p>';
    $html.='<table><thead><tr><th style="width:16%">Date &amp; Time (PH)</th><th style="width:23%">User / Staff ID</th><th style="width:11%">Role</th><th style="width:17%">Module</th><th style="width:22%">Activity</th><th style="width:11%">Status</th></tr></thead><tbody>';
    foreach($data['records']as$r)$html.='<tr><td>'.$e($r['local_time']).'<br><small>AUD-'.$r['id'].'</small></td><td>'.$wrap($r['actor'],29).'<br><small>'.$wrap($r['identifier'],30).($r['admin_id']?' / USER-'.$r['admin_id']:'').'</small></td><td>'.$wrap(ucfirst($r['role']),14).'</td><td>'.$wrap($r['module'],22).'</td><td>'.$wrap($r['description'],28).'<br><small>'.$wrap($r['reference'],28).'</small></td><td>'.$e($r['status_label']).'</td></tr>';
    if(!$data['records'])$html.='<tr><td colspan="6"><strong>No Audit Records Found</strong><br>No recorded activities match your selected date or filters.</td></tr>';
    return $html.'</tbody></table><p class="privacy">THE CELANDINE - System Audit Log Report - Complete authorized snapshot of the selected filters.</p></body></html>';
}
function auditReportPdf(array $data): string {
    $options=new Dompdf\Options();$options->set('isRemoteEnabled',false);$options->set('isPhpEnabled',false);$options->setChroot(dirname(__DIR__));
    $pdf=new Dompdf\Dompdf($options);$pdf->loadHtml(auditReportHtml($data),'UTF-8');$pdf->setPaper('A4','landscape');$pdf->render();$pdf->getCanvas()->page_text(28,570,'THE CELANDINE | Confidential                                      Page {PAGE_NUM} of {PAGE_COUNT}','DejaVu Sans',8,[.35,.4,.48]);return $pdf->output();
}
/** Fixed A4-ratio high-resolution pages. GD and bundled fonts already power staff reports. */
function auditReportPngPages(array $data): Generator {
    if(!extension_loaded('gd')||!function_exists('imagettftext'))throw new RuntimeException('PNG export requires the existing GD/FreeType support.');
    $font=dirname(__DIR__).'/vendor/dompdf/dompdf/lib/fonts/DejaVuSans.ttf';$bold=dirname(__DIR__).'/vendor/dompdf/dompdf/lib/fonts/DejaVuSans-Bold.ttf';if(!is_file($font)||!is_file($bold))throw new RuntimeException('Report fonts are unavailable.');
    $line=static function(string $text,int $size=17,bool $heavy=false)use($font,$bold):array {$fits=static function($s)use($size,$heavy,$font,$bold){$box=imagettfbbox($size,0,$heavy?$bold:$font,$s);return max($box[0],$box[2],$box[4],$box[6])-min($box[0],$box[2],$box[4],$box[6])<=1080;};return array_map(static fn($s)=>[$s,$size,$heavy],jrWrapLines($text,$fits));};
    $meta=array_merge($line('SYSTEM AUDIT LOG REPORT',24,true),$line('Reporting Period: '.$data['period']['label'],17,true),$line('Applied Filters: '.$data['filters'],15),$line('Generated: '.$data['generated_at'].' (Asia/Manila)',15),$line('Generated By: '.$data['actor']['name'].' / USER-'.$data['actor']['id'],15),$line('Total Matching Audit Records: '.$data['total'],16,true));
    $height=static fn(array $lines):int=>array_sum(array_map(static fn($l)=>(int)ceil($l[1]*1.65),$lines));$capacity=1450-$height($meta);$chunks=[];$chunk=[];$used=0;
    foreach($data['records']as$r){$block=array_merge($line($r['local_time'].' | AUD-'.$r['id'].' | '.$r['status_label'],17,true),$line($r['actor'].' | '.$r['identifier'].($r['admin_id']?' / USER-'.$r['admin_id']:'').' | '.ucfirst($r['role']),16),$line($r['module'].' | '.$r['description'],17),$line('Target: '.$r['reference'],15),[['',10,false]]);$h=$height($block);if($chunk&&$used+$h>$capacity){$chunks[]=$chunk;$chunk=[];$used=0;}foreach($block as$l)$chunk[]=$l;$used+=$h;}
    if(!$data['records'])$chunk=$line('No Audit Records Found. No recorded activities match your selected date or filters.');if($chunk)$chunks[]=$chunk;
    foreach($chunks as$index=>$records){$im=imagecreatetruecolor(1240,1754);$ink=imagecolorallocate($im,24,34,54);$muted=imagecolorallocate($im,86,101,122);$orange=imagecolorallocate($im,180,83,9);imagefill($im,0,0,imagecolorallocate($im,255,255,255));$logo=imagecreatefrompng(dirname(__DIR__).'/assets/branding/email-brand-light.png');$h=(int)(380*imagesy($logo)/imagesx($logo));imagecopyresampled($im,$logo,80,45,0,0,380,$h,imagesx($logo),imagesy($logo));imagedestroy($logo);imageline($im,80,125,1160,125,$orange);
        $y=165;foreach(array_merge($meta,[['',12,false]],$records)as[$text,$size,$heavy]){imagettftext($im,$size,0,80,$y,$ink,$heavy?$bold:$font,$text);$y+=(int)ceil($size*1.65);}imagettftext($im,12,0,80,1670,$muted,$font,'Historical outcomes are not inferred. Private metadata is withheld.');imagettftext($im,12,0,80,1700,$muted,$font,'THE CELANDINE | Confidential');imagettftext($im,12,0,1000,1700,$muted,$font,'Page '.($index+1).' / '.count($chunks));ob_start();imagepng($im);$bytes=(string)ob_get_clean();imagedestroy($im);yield ['number'=>$index+1,'total'=>count($chunks),'bytes'=>$bytes];
    }
}
function auditReportExportEvent(mysqli $db,array $data,string $format): void {
    if(!logAudit('export','audit_export',null,strtoupper($format).'; '.$data['total'].' authorized records; '.$data['period']['filename'],$db,'success'))throw new RuntimeException('Unable to record the audit export.');
}
function auditReportDownload(mysqli $db,array $data,string $format): void {
    if($format==='preview'){header('Content-Type: text/html; charset=utf-8');echo auditReportHtml($data);return;}
    if($format==='pdf'){$bytes=auditReportPdf($data);auditReportExportEvent($db,$data,$format);header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.auditReportName($data,'pdf').'"');echo $bytes;return;}
    if($format!=='png')throw new DomainException('Choose PDF, PNG or Preview Report.');$pages=auditReportPngPages($data);$pages->rewind();$first=$pages->current();
    if($first['total']===1){auditReportExportEvent($db,$data,$format);header('Content-Type: image/png');header('Content-Disposition: attachment; filename="'.auditReportName($data,'png').'"');echo $first['bytes'];return;}
    if(!class_exists('ZipArchive'))throw new RuntimeException('Multi-page image export requires PHP ZIP.');$directory=realpath(sys_get_temp_dir());if(!$directory)throw new RuntimeException('Private export staging is unavailable.');
    foreach([dirname(__DIR__),dirname(__DIR__,2),$_SERVER['DOCUMENT_ROOT']??'']as$public)if($public&&realpath($public)&&visitorPathWithin($directory,realpath($public)))throw new RuntimeException('Export staging must be outside public directories.');
    $tmp=tempnam($directory,'condo-audit-');if(!$tmp)throw new RuntimeException('Private export staging is unavailable.');$zip=new ZipArchive();$open=false;
    try{if(!chmod($tmp,0600)||$zip->open($tmp,ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Unable to prepare report images.');$open=true;foreach($pages as$page){$name='AuditLog_'.$data['period']['filename'].'_Part'.$page['number'].'.png';if(!$zip->addFromString($name,$page['bytes']))throw new RuntimeException('Unable to include every report page.');}if(!$zip->close())throw new RuntimeException('Unable to finish image archive.');$open=false;auditReportExportEvent($db,$data,$format);header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.auditReportName($data,'zip').'"');readfile($tmp);}finally{if($open)$zip->close();if(is_file($tmp))unlink($tmp);}
}
